import{_ as d,C as p,o as i,c as h,a7 as l,b as o,w as e,a as t,E as c,a8 as s,j as r}from"./chunks/framework.DmcojIVA.js";const C=JSON.parse('{"title":"可观测性：分布式链路追踪","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/distributed-system/observability-trace.md","filePath":"development/common/distributed-system/observability-trace.md","lastUpdated":1785428463000}'),E={name:"development/common/distributed-system/observability-trace.md"};function u(g,a,b,A,B,m){const n=p("Mermaid");return i(),h("div",null,[a[3]||(a[3]=l(`<h1 id="ke-guan-ce-xingfen-bu-shi-lian-lu-zhui-zong" tabindex="-1">可观测性：分布式链路追踪 <a class="header-anchor" href="#ke-guan-ce-xingfen-bu-shi-lian-lu-zhui-zong" aria-label="Permalink to &quot;可观测性：分布式链路追踪&quot;">​</a></h1><p>分布式链路追踪（Distributed Tracing）记录一次请求或业务动作在多个服务中的执行路径。它把各进程中的局部操作关联起来，用于定位延迟来源、错误传播路径和服务依赖关系。</p><p>日志擅长解释离散事件，指标擅长展示整体趋势；Trace 则提供一次请求的因果上下文和时间结构。</p><h2 id="he-xin-gai-nian" tabindex="-1">核心概念 <a class="header-anchor" href="#he-xin-gai-nian" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="trace" tabindex="-1">Trace <a class="header-anchor" href="#trace" aria-label="Permalink to &quot;Trace&quot;">​</a></h3><p>Trace 表示一个端到端操作，由共享同一 <code>trace_id</code> 的多个 Span 组成。例如，“用户提交订单”可以是一条 Trace。</p><p>Trace 经常以父子树展示，但现实中的异步批处理、扇入和扇出可能需要 Span Link 表达多对多关系，因此数据模型不一定只是简单的树。</p><h3 id="span" tabindex="-1">Span <a class="header-anchor" href="#span" aria-label="Permalink to &quot;Span&quot;">​</a></h3><p>Span 表示一个工作单元，例如：</p><ul><li>接收一次 HTTP 请求；</li><li>发起一次 RPC 调用；</li><li>执行一次数据库查询；</li><li>发布或消费一条消息；</li><li>执行“库存预占”这样的业务步骤。</li></ul><p>一个 Span 通常包含名称、开始时间、持续时间、状态、属性、事件、父 Span ID 和 Link。异常堆栈适合记录为 Span Event 或关联日志，而不是塞进高基数的指标标签。</p><h3 id="span-context" tabindex="-1">Span Context <a class="header-anchor" href="#span-context" aria-label="Permalink to &quot;Span Context&quot;">​</a></h3><p>Span Context 是需要跨进程传播的最小身份信息，核心包括：</p><ul><li><code>trace_id</code>：标识整条 Trace；</li><li><code>span_id</code>：标识当前 Span；</li><li>Trace Flags：包括采样提示；</li><li>Trace State：携带厂商扩展状态。</li></ul><h3 id="resource" tabindex="-1">Resource <a class="header-anchor" href="#resource" aria-label="Permalink to &quot;Resource&quot;">​</a></h3><p>Resource 描述产生 Span 的实体，例如 <code>service.name</code>、<code>service.version</code>、容器、Pod、区域和环境。没有稳定的资源属性，同名 Span 很难被正确归属。</p><h3 id="baggage" tabindex="-1">Baggage <a class="header-anchor" href="#baggage" aria-label="Permalink to &quot;Baggage&quot;">​</a></h3><p>Baggage 是随上下文传播的业务键值对，但不会自动成为 Span 属性。它会跨越服务边界并增加请求体积，因此不应放入密码、Token、个人信息或无界大字段。</p><h2 id="yi-tiao-trace-ru-he-xing-cheng" tabindex="-1">一条 Trace 如何形成 <a class="header-anchor" href="#yi-tiao-trace-ru-he-xing-cheng" aria-label="Permalink to &quot;一条 Trace 如何形成&quot;">​</a></h2><p>假设网关调用订单服务，订单服务再访问库存和数据库：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trace 4bf92f3577b34da6a3ce929d0e0e4736</span></span>
<span class="line"><span>└─ gateway: POST /orders</span></span>
<span class="line"><span>   └─ order-service: create-order</span></span>
<span class="line"><span>      ├─ inventory-service: reserve-stock</span></span>
<span class="line"><span>      └─ database: INSERT orders</span></span></code></pre></div>`,21)),(i(),o(s,null,{default:e(()=>[c(n,{id:"mermaid-104",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20C%20as%20%E5%AE%A2%E6%88%B7%E7%AB%AF%0A%20%20%20%20participant%20G%20as%20API%20Gateway%0A%20%20%20%20participant%20O%20as%20Order%20Service%0A%20%20%20%20participant%20I%20as%20Inventory%20Service%0A%20%20%20%20C-%3E%3EG%3A%20POST%20%2Forders%0A%20%20%20%20Note%20over%20G%3A%20%E5%88%9B%E5%BB%BA%E6%A0%B9%20Span%20%E4%B8%8E%20Trace%20ID%0A%20%20%20%20G-%3E%3EO%3A%20POST%20%2Forders%20%2B%20traceparent%0A%20%20%20%20Note%20over%20O%3A%20%E6%8F%90%E5%8F%96%E4%B8%8A%E4%B8%8B%E6%96%87%EF%BC%8C%E5%88%9B%E5%BB%BA%E6%9C%8D%E5%8A%A1%E7%AB%AF%20Span%0A%20%20%20%20O-%3E%3EI%3A%20POST%20%2Freservations%20%2B%20traceparent%0A%20%20%20%20Note%20over%20I%3A%20%E5%88%9B%E5%BB%BA%E5%AD%90%20Span%EF%BC%8C%E8%AE%B0%E5%BD%95%E5%BA%93%E5%AD%98%E5%B1%9E%E6%80%A7%0A%20%20%20%20I--%3E%3EO%3A%20%E9%A2%84%E5%8D%A0%E6%88%90%E5%8A%9F%0A%20%20%20%20O--%3E%3EG%3A%20%E8%AE%A2%E5%8D%95%E5%88%9B%E5%BB%BA%E6%88%90%E5%8A%9F%0A%20%20%20%20G--%3E%3EC%3A%20201%20Created%0A%20%20%20%20Note%20over%20G%2CI%3A%20%E5%90%84%20Span%20%E5%BC%82%E6%AD%A5%E5%AF%BC%E5%87%BA%EF%BC%8C%E5%90%8E%E7%AB%AF%E6%8C%89%20trace_id%20%E8%81%9A%E5%90%88%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l(`<blockquote><p>图示参考：<a href="https://www.w3.org/TR/trace-context/" target="_blank" rel="noreferrer">W3C Trace Context</a> 与 <a href="https://opentelemetry.io/docs/concepts/context-propagation/" target="_blank" rel="noreferrer">OpenTelemetry Context Propagation</a></p></blockquote><p>实际自动埋点可能同时产生客户端 Span 和服务端 Span，所以界面中会看到更细的层级。概念流程如下：</p><ol><li>入口收到请求，没有合法的上游上下文时创建根 Span。</li><li>调用下游前创建子 Span，并把当前 Span Context 注入载体。</li><li>下游提取上下文，以调用方 Span 为父级创建新 Span。</li><li>Span 完成后异步导出，不应让追踪后端故障阻塞业务请求。</li><li>后端按 <code>trace_id</code> 聚合 Span，并展示瀑布图或依赖关系。</li></ol><h2 id="w3c-trace-context" tabindex="-1">W3C Trace Context <a class="header-anchor" href="#w3c-trace-context" aria-label="Permalink to &quot;W3C Trace Context&quot;">​</a></h2><p>HTTP 场景应优先使用 W3C Trace Context 标准。<code>traceparent</code> 的格式为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>traceparent: version-trace_id-parent_id-trace_flags</span></span></code></pre></div><p>示例：</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">traceparent</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01</span></span></code></pre></div><p>其中 <code>00</code> 是版本，32 个十六进制字符是 Trace ID，16 个十六进制字符是调用方当前操作的 ID，<code>01</code> 表示 sampled 标志已设置。<code>tracestate</code> 是可选的厂商扩展字段。</p><p>注意安全边界：来自公网的 Trace Context 是不可信输入。入口应校验格式、限制 Baggage，并避免让外部调用者任意操纵采样成本或把恶意字段传播到内部系统。</p><h2 id="tong-bu-yu-yi-bu-chuan-bo" tabindex="-1">同步与异步传播 <a class="header-anchor" href="#tong-bu-yu-yi-bu-chuan-bo" aria-label="Permalink to &quot;同步与异步传播&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>载体</th><th>关系</th></tr></thead><tbody><tr><td>HTTP</td><td><code>traceparent</code>、<code>tracestate</code> Header</td><td>通常为父子关系</td></tr><tr><td>gRPC</td><td>Metadata</td><td>通常为父子关系</td></tr><tr><td>消息队列</td><td>Message Headers / Properties</td><td>可能为父子关系或 Span Link</td></tr><tr><td>进程内异步任务</td><td>语言运行时 Context</td><td>需要跨线程或协程正确传递</td></tr></tbody></table><p>消息消费的生命周期可能远长于生产请求。对于批量消费、多生产者合并或需要独立保留期的流程，创建新 Trace 并用 Span Link 指向生产端，通常比构造一棵巨大且长期不结束的父子树更清晰。</p><h2 id="mai-dian-ce-lue" tabindex="-1">埋点策略 <a class="header-anchor" href="#mai-dian-ce-lue" aria-label="Permalink to &quot;埋点策略&quot;">​</a></h2><h3 id="zi-dong-mai-dian" tabindex="-1">自动埋点 <a class="header-anchor" href="#zi-dong-mai-dian" aria-label="Permalink to &quot;自动埋点&quot;">​</a></h3><p>自动埋点通过 Agent、SDK 集成或框架插件捕获 HTTP、gRPC、数据库和消息队列调用。它适合快速获得技术调用图，并统一传播上下文。</p><h3 id="shou-dong-mai-dian" tabindex="-1">手动埋点 <a class="header-anchor" href="#shou-dong-mai-dian" aria-label="Permalink to &quot;手动埋点&quot;">​</a></h3><p>手动埋点表达业务边界，例如“计算优惠”“库存预占”“风控检查”。Span 名称应稳定、低基数：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>推荐：POST /orders</span></span>
<span class="line"><span>推荐：order.create</span></span>
<span class="line"><span>避免：POST /orders/ord_8f72d1</span></span>
<span class="line"><span>避免：为用户 10392 创建订单</span></span></code></pre></div><p>订单号、用户类型等动态值应放入属性，并经过敏感性与基数评估。</p><h3 id="bi-mian-chong-fu-he-guo-du-mai-dian" tabindex="-1">避免重复和过度埋点 <a class="header-anchor" href="#bi-mian-chong-fu-he-guo-du-mai-dian" aria-label="Permalink to &quot;避免重复和过度埋点&quot;">​</a></h3><ul><li>不要在已经自动埋点的 HTTP 调用外再创建语义相同的手动 Span。</li><li>不要给每个普通函数都创建 Span；优先选择远程调用、显著耗时和业务边界。</li><li>统一 Semantic Conventions，避免 <code>http.method</code>、<code>method</code>、<code>request_method</code> 并存。</li><li>记录错误状态时同时保留异常类型和必要事件，但避免重复打印多份堆栈。</li></ul><h2 id="cai-yangcheng-ben-yu-zhen-duan-jie-zhi-de-ping-heng" tabindex="-1">采样：成本与诊断价值的平衡 <a class="header-anchor" href="#cai-yangcheng-ben-yu-zhen-duan-jie-zhi-de-ping-heng" aria-label="Permalink to &quot;采样：成本与诊断价值的平衡&quot;">​</a></h2><p>全量追踪会产生显著的网络、处理和存储成本，因此高流量系统通常需要采样。</p><h3 id="tou-bu-cai-yang" tabindex="-1">头部采样 <a class="header-anchor" href="#tou-bu-cai-yang" aria-label="Permalink to &quot;头部采样&quot;">​</a></h3><p>头部采样在请求开始或 Trace 尚未完整时作决定。</p><p>优点：</p><ul><li>实现简单、资源开销低；</li><li>可根据 Trace ID 做一致概率采样，避免只保留半条 Trace。</li></ul><p>局限：</p><ul><li>作决定时还不知道请求最终是否失败或变慢；</li><li>可能错过低频但重要的异常。</li></ul><h3 id="wei-bu-cai-yang" tabindex="-1">尾部采样 <a class="header-anchor" href="#wei-bu-cai-yang" aria-label="Permalink to &quot;尾部采样&quot;">​</a></h3><p>尾部采样在 Collector 收集到一条 Trace 的全部或大部分 Span 后再决定，能够优先保留：</p><ul><li>包含错误的 Trace；</li><li>总延迟超过阈值的 Trace；</li><li>新版本、特定租户或低流量关键接口的 Trace。</li></ul><p>它需要暂存和按 Trace ID 汇聚数据，状态更多、延迟和资源成本更高。负载均衡必须确保同一 Trace 的 Span 能到达同一个采样决策点。</p><h3 id="she-ji-cai-yang-ce-lue" tabindex="-1">设计采样策略 <a class="header-anchor" href="#she-ji-cai-yang-ce-lue" aria-label="Permalink to &quot;设计采样策略&quot;">​</a></h3><ul><li>低流量关键交易可以全量保留，高流量健康请求按比例采样。</li><li>错误和高延迟 Trace 提高保留率，但仍要设置全局容量上限。</li><li>记录实际采样率，避免从样本数量直接推断总请求量。</li><li>指标适合统计总体错误率和延迟分布，Trace 样本适合解释原因；不要互相替代。</li></ul>`,36)),(i(),o(s,null,{default:e(()=>[c(n,{id:"mermaid-361",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%E8%AF%B7%E6%B1%82%E8%BF%9B%E5%85%A5%EF%BC%8C%E7%94%9F%E6%88%90%20Trace%20ID%22%5D%20--%3E%20B%7B%22%E5%A4%B4%E9%83%A8%E9%87%87%E6%A0%B7%E5%86%B3%E7%AD%96%22%7D%0A%20%20%20%20B%20--%3E%7C%E4%B8%8D%E8%AE%B0%E5%BD%95%7C%20X%5B%22%E5%81%9C%E6%AD%A2%E8%AE%B0%E5%BD%95%E4%B8%8E%E5%AF%BC%E5%87%BA%3Cbr%3E%E5%90%8E%E7%BB%AD%E6%97%A0%E6%B3%95%E7%94%B1%E5%B0%BE%E9%83%A8%E9%87%87%E6%A0%B7%E6%81%A2%E5%A4%8D%22%5D%0A%20%20%20%20B%20--%3E%7C%E8%AE%B0%E5%BD%95%7C%20C%5B%22%E5%90%84%E6%9C%8D%E5%8A%A1%E4%BA%A7%E7%94%9F%20Span%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22Collector%20%E6%8C%89%20trace_id%20%E6%B1%87%E8%81%9A%22%5D%0A%20%20%20%20D%20--%3E%20E%7B%22%E5%B0%BE%E9%83%A8%E9%87%87%E6%A0%B7%E8%A7%84%E5%88%99%22%7D%0A%20%20%20%20E%20--%3E%7C%E9%94%99%E8%AF%AF%E3%80%81%E9%AB%98%E5%BB%B6%E8%BF%9F%E3%80%81%E5%85%B3%E9%94%AE%E4%B8%9A%E5%8A%A1%7C%20F%5B%22%E4%BF%9D%E7%95%99%E5%B9%B6%E5%AF%BC%E5%87%BA%E5%AE%8C%E6%95%B4%20Trace%22%5D%0A%20%20%20%20E%20--%3E%7C%E6%99%AE%E9%80%9A%E5%81%A5%E5%BA%B7%E6%B5%81%E9%87%8F%7C%20G%7B%22%E6%A6%82%E7%8E%87%E6%88%96%E9%A2%84%E7%AE%97%E6%98%AF%E5%90%A6%E5%85%81%E8%AE%B8%EF%BC%9F%22%7D%0A%20%20%20%20G%20--%3E%7C%E6%98%AF%7C%20F%0A%20%20%20%20G%20--%3E%7C%E5%90%A6%7C%20H%5B%22%E4%B8%A2%E5%BC%83%20Trace%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r("blockquote",null,[r("p",null,[t("图示参考："),r("a",{href:"https://opentelemetry.io/docs/concepts/sampling/",target:"_blank",rel:"noreferrer"},"OpenTelemetry Sampling")])],-1)),a[6]||(a[6]=r("h2",{id:"cai-ji-yu-cun-chu-jia-gou",tabindex:"-1"},[t("采集与存储架构 "),r("a",{class:"header-anchor",href:"#cai-ji-yu-cun-chu-jia-gou","aria-label":'Permalink to "采集与存储架构"'},"​")],-1)),(i(),o(s,null,{default:e(()=>[c(n,{id:"mermaid-370",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E5%B7%B2%E5%9F%8B%E7%82%B9%E5%BA%94%E7%94%A8%3Cbr%3EOpenTelemetry%20SDK%20%2F%20Agent%22%5D%20--%3E%7COTLP%7C%20B%5B%22%E6%9C%AC%E5%9C%B0%E6%88%96%E8%8A%82%E7%82%B9%20Collector%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22Gateway%20Collector%3Cbr%3E%E8%BF%87%E6%BB%A4%E3%80%81%E8%B7%AF%E7%94%B1%E3%80%81%E5%B0%BE%E9%83%A8%E9%87%87%E6%A0%B7%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22Trace%20Backend%3Cbr%3EJaeger%20%2F%20Tempo%20%2F%20Zipkin%20%2F%20SkyWalking%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E6%9F%A5%E8%AF%A2%E4%B8%8E%E5%8F%AF%E8%A7%86%E5%8C%96%22%5D%0A"})]),fallback:e(()=>[...a[2]||(a[2]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<blockquote><p>图示参考：<a href="https://opentelemetry.io/docs/collector/" target="_blank" rel="noreferrer">OpenTelemetry Collector</a>、<a href="https://research.google/pubs/dapper-a-large-scale-distributed-systems-tracing-infrastructure/" target="_blank" rel="noreferrer">Dapper 论文</a> 与各 Trace Backend 官方文档。</p></blockquote><p>OpenTelemetry 负责产生、传播、处理和导出遥测数据，不是 Trace 存储后端。Collector 能让应用与具体后端解耦，并集中完成批处理、重试、脱敏和采样。</p><table tabindex="0"><thead><tr><th>后端</th><th>主要特点</th><th>适用考虑</th></tr></thead><tbody><tr><td>Jaeger</td><td>专注分布式追踪，提供查询和可视化</td><td>通用微服务追踪、OpenTelemetry 生态</td></tr><tr><td>Zipkin</td><td>架构简单，项目历史成熟</td><td>学习、已有 Zipkin/Brave 体系</td></tr><tr><td>Grafana Tempo</td><td>与 Grafana、Loki、Prometheus 关联紧密，使用对象存储</td><td>已有 Grafana 技术栈、大规模 Trace</td></tr><tr><td>Apache SkyWalking</td><td>同时提供探针、拓扑、指标、日志和追踪能力</td><td>希望使用一体化 APM 平台</td></tr></tbody></table><p>选型时应验证接收协议、属性检索、保留策略、多租户、对象存储或数据库成本，以及从指标和日志跳转到 Trace 的体验。</p><h2 id="ru-he-yue-du-yi-zhang-trace-pu-bu-tu" tabindex="-1">如何阅读一张 Trace 瀑布图 <a class="header-anchor" href="#ru-he-yue-du-yi-zhang-trace-pu-bu-tu" aria-label="Permalink to &quot;如何阅读一张 Trace 瀑布图&quot;">​</a></h2><p>不要只寻找“最长的横条”，应按下面顺序判断：</p><ol><li><strong>根 Span 总耗时</strong>：是否与用户观测到的延迟一致？</li><li><strong>关键路径</strong>：哪些串行 Span 真正决定端到端耗时？</li><li><strong>空白时间</strong>：可能来自排队、线程池等待、锁竞争或缺失埋点。</li><li><strong>重复调用</strong>：是否存在意外重试、N+1 查询或循环 RPC？</li><li><strong>错误传播</strong>：错误从哪个 Span 开始，哪些上游只是被动失败？</li><li><strong>服务端与客户端耗时差</strong>：差值可能来自网络、代理、连接池和排队。</li><li><strong>属性差异</strong>：慢请求是否集中在特定版本、区域、接口或依赖。</li></ol><p>一条 Trace 只能证明这次请求发生了什么。判断是否为系统性问题，还要回到指标查看频率和影响范围。</p><h2 id="chang-jian-gu-zhang-yu-pai-cha" tabindex="-1">常见故障与排查 <a class="header-anchor" href="#chang-jian-gu-zhang-yu-pai-cha" aria-label="Permalink to &quot;常见故障与排查&quot;">​</a></h2><h3 id="trace-duan-lie" tabindex="-1">Trace 断裂 <a class="header-anchor" href="#trace-duan-lie" aria-label="Permalink to &quot;Trace 断裂&quot;">​</a></h3><p>现象：下游出现新的 Trace ID。</p><p>检查：</p><ul><li>客户端是否注入、服务端是否提取 W3C 上下文；</li><li>代理是否删除了 Header；</li><li>消息属性是否被序列化和消费框架保留；</li><li>跨线程、协程时是否丢失语言 Context。</li></ul><h3 id="trace-zhi-you-yi-ban" tabindex="-1">Trace 只有一半 <a class="header-anchor" href="#trace-zhi-you-yi-ban" aria-label="Permalink to &quot;Trace 只有一半&quot;">​</a></h3><p>可能是部分服务未埋点、采样决定不一致、应用退出前未刷新、Exporter 被限流，或 Collector 队列溢出。应同时监控 Collector 的接收、拒绝、排队和导出失败指标。</p><h3 id="trace-shu-liang-tu-ran-xia-jiang" tabindex="-1">Trace 数量突然下降 <a class="header-anchor" href="#trace-shu-liang-tu-ran-xia-jiang" aria-label="Permalink to &quot;Trace 数量突然下降&quot;">​</a></h3><p>不要直接推断业务流量下降。先对照独立的请求指标，再检查采样配置、SDK、Collector 和后端写入限额。</p><h3 id="cha-xun-cheng-ben-guo-gao" tabindex="-1">查询成本过高 <a class="header-anchor" href="#cha-xun-cheng-ben-guo-gao" aria-label="Permalink to &quot;查询成本过高&quot;">​</a></h3><p>限制无界属性，把动态 ID 放在属性而不是 Span 名称中；根据查询需求设置保留周期和索引字段，并用指标先缩小时间、服务和版本范围。</p><h2 id="shi-jian-lian-xi" tabindex="-1">实践练习 <a class="header-anchor" href="#shi-jian-lian-xi" aria-label="Permalink to &quot;实践练习&quot;">​</a></h2><p>可以使用 <a href="https://opentelemetry.io/docs/demo/" target="_blank" rel="noreferrer">OpenTelemetry Demo</a> 观察一个多服务系统：</p><ol><li>发起一次正常请求，找到根 Span 和关键路径。</li><li>根据 <code>trace_id</code> 跳转到对应日志。</li><li>注入一个服务延迟，比较客户端 Span 与服务端 Span 的耗时。</li><li>注入错误，检查 Span 状态、事件和日志是否一致。</li><li>修改采样策略，观察错误 Trace 的保留率以及 Collector 自身指标。</li></ol><h2 id="xue-xi-zi-ce" tabindex="-1">学习自测 <a class="header-anchor" href="#xue-xi-zi-ce" aria-label="Permalink to &quot;学习自测&quot;">​</a></h2><ol><li><code>trace_id</code> 与 <code>span_id</code> 分别解决什么问题？</li><li>为什么 Trace 通常表现为树，但异步系统中还需要 Span Link？</li><li>头部采样为什么可能错过错误请求，尾部采样又为什么更昂贵？</li><li>客户端 Span 比服务端 Span 多出 500 ms，可能有哪些原因？</li><li>Trace 数量下降时，为什么要先对照独立请求指标？</li></ol><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>W3C Recommendation：<a href="https://www.w3.org/TR/trace-context/" target="_blank" rel="noreferrer">Trace Context</a></li><li>OpenTelemetry：<a href="https://opentelemetry.io/docs/concepts/signals/traces/" target="_blank" rel="noreferrer">Traces</a></li><li>OpenTelemetry：<a href="https://opentelemetry.io/docs/concepts/context-propagation/" target="_blank" rel="noreferrer">Context Propagation</a></li><li>OpenTelemetry：<a href="https://opentelemetry.io/docs/concepts/sampling/" target="_blank" rel="noreferrer">Sampling</a></li><li>OpenTelemetry：<a href="https://opentelemetry.io/docs/collector/" target="_blank" rel="noreferrer">Collector</a></li><li>Benjamin H. Sigelman 等：<a href="https://research.google/pubs/dapper-a-large-scale-distributed-systems-tracing-infrastructure/" target="_blank" rel="noreferrer">Dapper, a Large-Scale Distributed Systems Tracing Infrastructure</a></li><li>OpenZipkin：<a href="https://zipkin.io/pages/architecture.html" target="_blank" rel="noreferrer">Architecture</a></li><li>Grafana Tempo：<a href="https://grafana.com/docs/tempo/latest/" target="_blank" rel="noreferrer">Documentation</a></li><li>Apache SkyWalking：<a href="https://skywalking.apache.org/docs/main/latest/readme/" target="_blank" rel="noreferrer">Documentation</a></li></ul>',26))])}const k=d(E,[["render",u]]);export{C as __pageData,k as default};
